{
  "title": "mngtListDetail",
  "type": "object",
  "properties": {
    "userId": {
      "type": "string",
      "description": "요청 사용자 ID. \"admin\"을 사용한다."
    },
    "mgmtOrgId": {
      "type": "string",
      "description": "조직 ID. 이전 단계가 확정한 orgId 값(예: org_000991)."
    },
    "asstType": {
      "type": "string",
      "description": "자산타입. 이전 단계가 확정한 값(예: SSRCCE)."
    },
    "templateNo": {
      "type": "string",
      "description": "진단템플릿 번호. 이전 단계가 확정한 값(예: 151)."
    },
    "diagYear": {
      "type": "string",
      "description": "기준연도. \"2026\"을 사용한다."
    },
    "asstLCtgrId": {
      "type": "string",
      "description": "자산분류(대) ID. 이전 단계 assetCategory 응답의 asstCtgrId 값(예: AT_0005382). 값을 모르면 이 필드를 생략한다."
    },
    "page": {
      "type": "integer",
      "description": "현재 페이지. 1부터 시작."
    },
    "pageSize": {
      "type": "integer",
      "description": "페이지당 항목 수. 200을 사용한다."
    },
    "filter": {
      "type": "object",
      "description": "미조치 필터. {\"xorStr\":{\"logic\":\"and\",\"filters\":[{\"field\":\"SECURITY_SCORE\",\"operator\":\"neq\",\"value\":\"100\"}]}}",
      "properties": {
        "xorStr": {
          "type": "object",
          "properties": {
            "logic": {
              "type": "string"
            },
            "filters": {
              "type": "array",
              "items": {
                "type": "object",
                "properties": {
                  "field": {
                    "type": "string"
                  },
                  "operator": {
                    "type": "string"
                  },
                  "value": {
                    "type": "string"
                  }
                }
              }
            }
          }
        }
      }
    }
  },
  "required": [
    "userId",
    "mgmtOrgId",
    "asstType",
    "templateNo"
  ],
  "additionalProperties": true,
  "strict": false
}

{
  "title": "scanResultCodeMngtDetailRequest",
  "type": "object",
  "properties": {
    "userId": {
      "type": "string",
      "description": "요청 사용자 ID (예: admin)"
    },
    "asstCode": {
      "type": "array",
      "description": "2단계 mngtListDetail 응답의 assetList[].asstCode 목록",
      "items": {
        "type": "string"
      }
    },
    "hostNm": {
      "type": "array",
      "description": "호스트명 배열. ⚠️ 전달하지 말 것 — asstCode와 AND 조건으로 걸려 결과가 0건이 된다(2026-08-18 검증).",
      "items": {
        "type": "string"
      }
    },
    "resultStatusCdListStr": {
      "type": "string",
      "description": "점검결과 리스트. \"[\\\"FAIL\\\"]\" 사용. ⚠️ 스펙표는 선택(N)이나 실제 필수값."
    },
    "vadaYn": {
      "type": "string",
      "description": "자산타입 VADA 여부. \"N\" 고정. ⚠️ 스펙표는 선택(N)이나 실제 필수값."
    },
    "severity": {
      "type": "string",
      "description": "취약도. 필수값이며 \"4\"(상)로 지정한다. 1(최하)~5(최상)."
    },
    "asstType": {
      "type": "string",
      "description": "자산타입 (2단계 assetCategory 응답과 동일 값)"
    },
    "atemplateNo": {
      "type": "string",
      "description": "진단템플릿 번호 (2단계 assetSsrcceTemplate 응답과 동일 값)"
    },
    "page": {
      "type": "integer",
      "description": "현재 페이지, 기본 1"
    },
    "pageSize": {
      "type": "integer",
      "description": "페이지당 항목 수. 반드시 50을 사용한다(검증된 성공값)."
    }
  },
  "additionalProperties": true,
  "strict": false,
  "required": [
    "userId",
    "asstCode",
    "resultStatusCdListStr",
    "vadaYn",
    "asstType",
    "severity"
  ]
}

